function shortestKitSlice(shelf, kit) {
  const need = new Map()
  for (const ch of kit) need.set(ch, (need.get(ch) ?? 0) + 1)
  let missing = kit.length
  let left = 0
  let bestStart = 0
  let bestLen = Infinity
  for (let r = 0; r < shelf.length; r++) {
    const ch = shelf[r]
    if ((need.get(ch) ?? 0) > 0) missing--
    need.set(ch, (need.get(ch) ?? 0) - 1)
    if (missing > 0) continue
    while (need.get(shelf[left]) < 0) {
      need.set(shelf[left], need.get(shelf[left]) + 1)
      left++
    }
    if (r - left + 1 < bestLen) {
      bestLen = r - left + 1
      bestStart = left
    }
    need.set(shelf[left], need.get(shelf[left]) + 1)
    missing++
    left++
  }
  return bestLen === Infinity ? '' : shelf.slice(bestStart, bestStart + bestLen)
}

