def shortest_kit_slice(shelf, kit):
    need = {}
    for ch in kit:
        need[ch] = need.get(ch, 0) + 1
    missing = len(kit)
    left = 0
    best_start, best_len = 0, float('inf')
    for r, ch in enumerate(shelf):
        if need.get(ch, 0) > 0:
            missing -= 1
        need[ch] = need.get(ch, 0) - 1
        if missing > 0:
            continue
        while need[shelf[left]] < 0:
            need[shelf[left]] += 1
            left += 1
        if r - left + 1 < best_len:
            best_start, best_len = left, r - left + 1
        need[shelf[left]] += 1
        missing += 1
        left += 1
    return '' if best_len == float('inf') else shelf[best_start:best_start + best_len]
